(()=>{function sync(){document.querySelectorAll('[data-slider-unit]').forEach(o=>{const i=document.getElementById(o.htmlFor);if(i)o.textContent=new Intl.NumberFormat('en-IE',{maximumFractionDigits:1}).format(Number(i.value))+' '+(Number(i.value)===1?o.dataset.sliderUnit.replace('labs','lab').replace('HPLCs','HPLC').replace('days','day').replace('weeks','week'):o.dataset.sliderUnit);});}document.querySelectorAll('#savings-calculator input[type=range]').forEach(i=>i.addEventListener('input',sync));document.addEventListener('resolve-model',sync);sync();})();